from ta_tshark_hex_parser.parser_factory import get_hex_parser


def get_parsed_messages_from_file(filepath, source_description=None):
    """
    Get list of Message objects for all messages in file.
    :param filepath:
    :param source_description: optional, non default source description. Must be matching source file column format
    :return:
    """
    parser = get_hex_parser(source_description)
    with open(filepath, 'r') as source_file:
        msg_list = parser.get_converted_msgs_list(source_file)
    return msg_list


def get_parsed_messages_from_string(source_string, source_description=None):
    """
    Get list of Message objects for all messages in string.
    :param source_string:
    :param source_description: optional, non default source description. Must be matching source file column format
    :return:
    """
    parser = get_hex_parser(source_description)
    msg_list = parser.get_converted_msgs_list(source_string)
    return msg_list


def get_unparsed_messages_generator(source_description=None, stop_condition=None):
    """
    Returns genarator of parsed messages from infinite source like actve process output.
    Source output must be matching source description.
    Genrator takes source object with read method as an input.
    :param source:
    :param source_description:
    :param stop_condition:
    :return: generator
    """
    parser = get_hex_parser(source_description, stop_condition=stop_condition)
    return parser.iter_unparsed_msg


def get_parsed_messages_generator(source_description=None, stop_condition=None):
    """
    Returns genarator of parsed messages from infinite source like actve process output.
    Source output must be matching source description.
    Genrator takes source object with read method as an input.
    :param source:
    :param source_description:
    :param stop_condition:
    :return: generator
    """
    parser = get_hex_parser(source_description, stop_condition=stop_condition)
    return parser.iter_parsed_msg
